    {status.problems.length > 0 && <Box flexDirection="column" marginTop={1}>
      <Text bold>Problems</Text>
      {status.problems.map(problem => <Text color="warning" wrap="wrap">{problem}</Text>)}
    </Box>}
  </Box>;
}

